// HasMonitor applies the HasEdge predicate on the "monitor" edge.
func HasMonitor() predicate.MonitorCheck {
	return predicate.MonitorCheck(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, MonitorTable, MonitorColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasMonitorWith applies the HasEdge predicate on the "monitor" edge with a given conditions (other predicates).
func HasMonitorWith(preds ...predicate.Monitor) predicate.MonitorCheck {
	return predicate.MonitorCheck(func(s *sql.Selector) {
		step := newMonitorStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.MonitorCheck) predicate.MonitorCheck {
	return predicate.MonitorCheck(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.MonitorCheck) predicate.MonitorCheck {
	return predicate.MonitorCheck(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.MonitorCheck) predicate.MonitorCheck {
	return predicate.MonitorCheck(sql.NotPredicates(p))
}
